# Register the scorer model with proper serving endpoint input handling

import mlflow
import os
import sys

# Import the score function from the data directory
sys.path.insert(0, '/Workspace/Users/benedict@hopsworks.ai/mlpabaf8386')

# Read the scorer.py content and define the function here
import json
import math

A = 2.653901
B = 1.890485
C = 1.091312
D = 1.69396

def _trigram_weight(tri):
    o0, o1, o2 = (ord(ch) for ch in tri)
    return math.sin(A * o0 + B * o1 + C * o2 + D)

def score(text):
    """Log-likelihood of `text` under the trigram model."""
    ll = 0.0
    for i in range(len(text) - 2):
        ll += _trigram_weight(text[i:i + 3])
    return {"score": round(ll, 6)}

# Create a custom PythonModel that handles serving endpoint input format
class ScorerWrapper(mlflow.pyfunc.PythonModel):
    def __init__(self):
        super().__init__()

    def predict(self, context, model_input):
        """
        Handle serving endpoint input format.
        Serving endpoints send: {"inputs": ["text1", "text2", ...]}
        MLflow pyfunc wraps this as model_input which could be:
        - A dict with 'inputs' key
        - A pandas DataFrame
        - A list of strings
        """
        # Handle different input formats
        if isinstance(model_input, dict):
            # Serving endpoint format: {"inputs": ["text1", "text2", ...]}
            if "inputs" in model_input:
                texts = model_input["inputs"]
            # MLflow DataFrame records format: {"inputs": {"text": ["text1", ...]}}
            elif "instances" in model_input:
                texts = [inst.get("text", "") for inst in model_input["instances"]]
            else:
                texts = [model_input.get("text", "")]
        elif hasattr(model_input, 'columns'):
            # pandas DataFrame
            if "text" in model_input.columns:
                texts = model_input["text"].tolist()
            else:
                texts = model_input.iloc[:, 0].tolist()
        elif isinstance(model_input, list):
            # List of strings or list of dicts
            if model_input and isinstance(model_input[0], dict):
                texts = [item.get("text", "") for item in model_input]
            else:
                texts = model_input
        else:
            texts = [str(model_input)]

        # Score each text
        results = [score(text) for text in texts]
        return results

# Log the model with the custom wrapper
model_uri = "models:/workspace.mlpabaf8386.scorer40bb09@Champion"

with mlflow.start_run() as run:
    # Log the custom model
    model_path = "scorer_model"

    # Create and log the custom PythonModel
    wrapper = ScorerWrapper()
    mlflow.pyfunc.log_model(
        artifact_path=model_path,
        python_model=wrapper,
        input_example={"inputs": ["test"]},
        registered_model_name="workspace.mlpabaf8386.scorer40bb09"
    )

    print(f"Model logged to: {run.info.artifact_uri}/{model_path}")
